commands:
set -eu
PKG=io.blueeye
SERVICE=io.blueeye/io.blueeye.service.ScannerService
adb start-server >/dev/null
SERIAL=$(adb devices | awk 'NR>1 && $2=="device"{print $1; exit}')
[ -n "$SERIAL" ] || { adb devices -l; exit 31; }
adbx(){ adb -s "$SERIAL" "$@"; }
service_count(){ adbx shell dumpsys activity services $PKG | grep -c 'ServiceRecord.*io.blueeye/.service.ScannerService' || true; }
adbx shell am force-stop $PKG; sleep 2
adbx shell svc bluetooth enable >/dev/null 2>&1 || true; sleep 3
echo SERVICE_BEFORE=$(service_count)
adbx shell am start -W -n $PKG/.MainActivity >/dev/null; sleep 2
echo SERVICE_AFTER_ACTIVITY=$(service_count)
adbx shell run-as $PKG am start-foreground-service --user 0 -a ACTION_START -n $SERVICE
sleep 6
echo SERVICE_AFTER_EXPLICIT=$(service_count)
adbx logcat -d -v threadtime | grep -E 'ScannerService: lifecycle=|SecurityException' | tail -100 || true
COUNT=$(service_count)
[ "$COUNT" -eq 1 ] || { echo ADB_SERVICE_SMOKE=FAIL; exit 32; }
echo ADB_SERVICE_SMOKE=PASS
adbx shell am force-stop $PKG
